        justify-content: space-between;
        gap: 1rem;
        margin-top: auto;
        padding-top: 1.2rem;
      }

      .price {
        font-size: 1.35rem;
        font-weight: 950;
      }

      .add-button {
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--surface-strong);
        color: var(--text);
        padding: 0.7rem 0.95rem;
        font-weight: 850;
      }

      .add-button:hover {
        border-color: var(--accent);
        background: rgba(255, 184, 92, 0.14);
      }

      .deals-layout {
        display: grid;
        grid-template-columns: 1.2fr 0.8fr;
        gap: 1rem;
      }

      .deal-panel {
        overflow: hidden;
        border-radius: 1.75rem;
        background:
          linear-gradient(135deg, rgba(255, 184, 92, 0.18), transparent 42%),
          var(--surface);
      }

      .deal-feature {
        padding: clamp(1.25rem, 3vw, 2.2rem);
      }

      .deal-feature h2 {
        margin-top: 0.8rem;
        font-size: clamp(2.1rem, 6vw, 4.9rem);
        letter-spacing: -0.06em;
      }

      .deal-feature p {
        max-width: 42rem;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .timer {
        display: flex;
        flex-wrap: wrap;
        gap: 0.7rem;
        margin: 1.5rem 0;
      }

      .timer span {
        display: grid;
        min-width: 5rem;
        border: 1px solid rgba(255, 255, 255, 0.12);
        border-radius: 1rem;
        background: rgba(0, 0, 0, 0.18);
        padding: 0.8rem;
        text-align: center;
      }

      .timer strong {
        font-size: 1.55rem;
      }

      .timer small {
        color: var(--muted);
        font-weight: 800;
        letter-spacing: 0.07em;
        text-transform: uppercase;
      }

      .deal-stack {
        display: grid;
        gap: 1rem;
      }

      .mini-deal {
        padding: 1.2rem;
      }

      .mini-deal strong {
        display: block;
        color: var(--accent);
        font-size: 2rem;
      }

      .mini-deal p {
        margin: 0.35rem 0 0;
        color: var(--muted);
      }

      .article-card {
        overflow: hidden;
        border-radius: 1.45rem;
      }

      .article-image {
        min-height: 13rem;
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.18), transparent 35%),
          linear-gradient(135deg, var(--article-a), var(--article-b));
      }

      .article-image-travel {
        --article-a: #34205d;
        --article-b: #141821;
      }

      .article-image-home {
        --article-a: #5b2f18;
        --article-b: #15191f;
      }

      .article-image-drop {
        --article-a: #0f4a45;
        --article-b: #121722;
      }

      .article-content {
        padding: 1.15rem;
      }

      .article-card a {
        display: inline-flex;
        margin-top: 1rem;
        color: var(--teal);
        font-weight: 900;
        text-decoration-thickness: 0.12em;
        text-underline-offset: 0.22em;
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1fr auto;
        align-items: center;
        gap: 1rem;
        margin-top: 4rem;
        border-radius: 1.75rem;
        padding: clamp(1.25rem, 3vw, 2rem);
      }

      .newsletter h2 {
        font-size: clamp(1.8rem, 4vw, 3rem);
      }

      .newsletter p {
        margin: 0.55rem 0 0;
        color: var(--muted);
      }

      .newsletter label {
        display: block;
        margin-bottom: 0.45rem;
        font-weight: 850;
      }

      .newsletter input {
        min-width: min(21rem, 100%);
        min-height: 3rem;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: #060910;
        color: var(--text);
        padding: 0.85rem 1rem;
      }

      .newsletter input[aria-invalid="true"] {
        border-color: var(--danger);
      }

      .form-status {
        min-height: 1.5rem;
        margin: 0.45rem 0 0;
        color: var(--muted);
      }

      .site-footer {
        border-top: 1px solid rgba(255, 255, 255, 0.1);
        background: rgba(0, 0, 0, 0.2);
        padding-block: 2rem;
      }

      .footer-inner {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        color: var(--muted);
      }

      .footer-links {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      .footer-links a {
        color: var(--muted);
        font-weight: 750;
      }

      .visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        white-space: nowrap;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .button,
        .cart-button,
        .add-button,
        .nav-toggle,
        .product-card,
        .deal-panel,
        .article-card,
        .newsletter {
          border: 1px solid ButtonText;
        }
      }

      @media (max-width: 860px) {
        .nav-toggle {
          display: inline-flex;
        }

        .primary-nav {
          position: fixed;
          inset: 4.5rem 1rem auto 1rem;
          display: none;
          flex-direction: column;
          align-items: stretch;
          border: 1px solid var(--border);
          border-radius: 1.25rem;
          background: #0b1018;
          padding: 0.75rem;
          box-shadow: var(--shadow);
        }

        .primary-nav[data-open="true"] {
          display: flex;
        }

        .primary-nav a {
          padding: 1rem;
        }

        .hero,
        .deals-layout,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .hero {
          min-height: auto;
        }

        .hero-card {
          min-height: 26rem;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .section-header {
          align-items: start;
          flex-direction: column;
        }

        .newsletter-row {
          align-items: stretch;
          flex-direction: column;
        }
      }

      @media (min-width: 861px) and (max-width: 1040px) {
        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }
