        <p>&copy; 2026 North &amp; Noir. Curated retail for modern nights.</p>
        <nav class="footer-links" aria-label="Footer navigation">
          <a href="#featured">Products</a>
          <a href="#deals">Deals</a>
          <a href="#editorial">Journal</a>
        </nav>
      </div>
    </footer>

    <script>
      const navToggle = document.querySelector(".nav-toggle");
      const primaryNav = document.querySelector("#primary-navigation");
      const cartCount = document.querySelector("#cart-count");
      const cartSummary = document.querySelector("#cart-summary");
      const bagStatus = document.querySelector("#bag-status");
      const addButtons = document.querySelectorAll(".add-button");
      const newsletterForm = document.querySelector("#newsletter-form");
      const emailInput = document.querySelector("#email");
      const emailStatus = document.querySelector("#email-status");
      const countdown = {
        hours: document.querySelector("#hours"),
        minutes: document.querySelector("#minutes"),
        seconds: document.querySelector("#seconds")
      };

      let bagItems = 0;
      let remainingSeconds = 12 * 60 * 60;

      function setNavigation(open) {
        navToggle.setAttribute("aria-expanded", String(open));
        primaryNav.dataset.open = String(open);
        document.body.classList.toggle("nav-open", open);
      }

      navToggle.addEventListener("click", () => {
        setNavigation(navToggle.getAttribute("aria-expanded") !== "true");
      });

      primaryNav.addEventListener("click", (event) => {
        if (event.target instanceof HTMLAnchorElement) {
          setNavigation(false);
        }
      });

      addButtons.forEach((button) => {
        button.addEventListener("click", () => {
          bagItems += 1;
          const productName = button.dataset.product;
          cartCount.textContent = String(bagItems);
          cartSummary.textContent = `${bagItems} ${bagItems === 1 ? "item" : "items"} in bag`;
          bagStatus.textContent = `${productName} added to bag. ${cartSummary.textContent}.`;
        });
      });

      function updateCountdown() {
        const hours = Math.floor(remainingSeconds / 3600);
        const minutes = Math.floor((remainingSeconds % 3600) / 60);
        const seconds = remainingSeconds % 60;
        countdown.hours.textContent = String(hours).padStart(2, "0");
        countdown.minutes.textContent = String(minutes).padStart(2, "0");
        countdown.seconds.textContent = String(seconds).padStart(2, "0");
        remainingSeconds = Math.max(remainingSeconds - 1, 0);
      }

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();
        const email = emailInput.value.trim();

        if (!email || !emailInput.validity.valid) {
          emailInput.setAttribute("aria-invalid", "true");
          emailStatus.textContent = "Enter a valid email address to join the insider list.";
          emailInput.focus();
          return;
        }

        emailInput.setAttribute("aria-invalid", "false");
        emailStatus.textContent = "You're on the list. Watch your inbox for the next drop.";
        newsletterForm.reset();
      });

      emailInput.addEventListener("input", () => {
        if (emailInput.getAttribute("aria-invalid") === "true" && emailInput.validity.valid) {
          emailInput.setAttribute("aria-invalid", "false");
          emailStatus.textContent = "";
        }
      });

      updateCountdown();
      window.setInterval(updateCountdown, 1000);
    </script>
