function hexToRgb(hex) { const n = Number.parseInt(hex.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function lum(hex) { return hexToRgb(hex).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0); }
function contrast(a, b) { const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x); return (l1 + 0.05) / (l2 + 0.05); }
const pairs = [
  ['body text', '#f6f7fb', '#080b10'],
  ['muted text', '#b8c0cf', '#111722'],
  ['accent text', '#ffb85c', '#111722'],
  ['teal text', '#7de2d1', '#111722'],
  ['primary button text', '#140c04', '#ffb85c'],
  ['focus indicator', '#7de2d1', '#080b10'],
  ['danger border/text', '#ff7a90', '#060910']
];
let failed = false;
for (const [name, fg, bg] of pairs) {
  const ratio = contrast(fg, bg);
  console.log(`${name}: ${ratio.toFixed(2)}:1`);
  if (ratio < 4.5) failed = true;
}
process.exit(failed ? 1 : 0);
