const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
const path = require('node:path');

(async () => {
  let browser;
  try {
    browser = await chromium.launch({ headless: true });
  } catch (error) {
    console.error(error.message);
    process.exit(2);
  }
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });
  const results = await page.evaluate(async () => window.axe.run());
  await browser.close();
  const wcag = results.violations.filter((v) => !v.tags.includes('best-practice'));
  const bestPractice = results.violations.filter((v) => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bestPractice: bestPractice.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
