const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
const path = require('node:path');

async function scan(page, label) {
  await page.addScriptTag({ path: axePath });
  const results = await page.evaluate(async () => window.axe.run());
  return {
    label,
    wcag: results.violations
      .filter((v) => !v.tags.includes('best-practice'))
      .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bestPractice: results.violations
      .filter((v) => v.tags.includes('best-practice'))
      .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
  };
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const fileUrl = 'file://' + path.resolve('index.html');
  const reports = [];

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await desktop.goto(fileUrl, { waitUntil: 'load' });
  reports.push(await scan(desktop, 'desktop'));

  const mobile = await browser.newPage({ viewport: { width: 375, height: 812 } });
  await mobile.goto(fileUrl, { waitUntil: 'load' });
  reports.push(await scan(mobile, 'mobile closed navigation'));
  await mobile.getByRole('button', { name: 'Menu' }).click();
  reports.push(await scan(mobile, 'mobile open navigation'));
  await mobile.getByRole('button', { name: 'Join the list' }).click();
  reports.push(await scan(mobile, 'mobile newsletter validation'));

  await browser.close();
  console.log(JSON.stringify(reports, null, 2));
  process.exit(reports.some((report) => report.wcag.length) ? 1 : 0);
})();
NODE
