       }

       .form-status {
         min-height: 1.5rem;
         margin: 0.45rem 0 0;
         color: var(--muted);
       }

       .site-footer {
         border-top: 1px solid rgba(255, 255, 255, 0.1);
         background: rgba(0, 0, 0, 0.2);
         padding-block: 2rem;
       }

       .footer-inner {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         color: var(--muted);
       }

       .footer-links {
         display: flex;
         flex-wrap: wrap;
         gap: 1rem;
       }

       .footer-links a {
         color: var(--muted);
         font-weight: 750;
       }

       .visually-hidden {
         position: absolute;
         width: 1px;
         height: 1px;
         overflow: hidden;
         clip: rect(0 0 0 0);
         clip-path: inset(50%);
         white-space: nowrap;
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         .button,
         .cart-button,
         .add-button,
         .nav-toggle,
         .product-card,
         .deal-panel,
         .article-card,
         .newsletter {
           border: 1px solid ButtonText;
         }
       }

       @media (max-width: 860px) {
         .nav-toggle {
           display: inline-flex;
         }

         .primary-nav {
           position: fixed;
           inset: 4.5rem 1rem auto 1rem;
           display: none;
           flex-direction: column;
           align-items: stretch;
           border: 1px solid var(--border);
           border-radius: 1.25rem;
           background: #0b1018;
           padding: 0.75rem;
           box-shadow: var(--shadow);
         }

         .primary-nav[data-open="true"] {
           display: flex;
         }

         .primary-nav a {
           padding: 1rem;
         }

         .hero,
         .deals-layout,
         .newsletter {
           grid-template-columns: 1fr;
         }

         .hero {
           min-height: auto;
         }

         .hero-card {
           min-height: 26rem;
         }

         .product-grid,
         .editorial-grid {
           grid-template-columns: 1fr;
         }

         .section-header {
           align-items: start;
           flex-direction: column;
         }

         .newsletter-row {
           align-items: stretch;
           flex-direction: column;
         }
       }

       @media (min-width: 861px) and (max-width: 1040px) {
         .product-grid,
         .editorial-grid {
           grid-template-columns: repeat(2, minmax(0, 1fr));
         }
       }
     </style>
   </head>
